#include <vector>
#include "convolutionFFT2D.cu"
bool save(const char*p,const std::vector<float>&v){FILE*f=fopen(p,"wb");if(!f)return false;bool ok=fwrite(v.data(),4,v.size(),f)==v.size();fclose(f);return ok;}
int main(){const int x=64,y=32,padding=16,n=y*(x+padding)*2;std::vector<float>a(n),b(n),out(n+8,-77);unsigned seed=123;for(int i=0;i<n;i++){seed=seed*1664525u+1013904223u;a[i]=float(int(seed>>16)-32768)/32768.f;seed=seed*1664525u+1013904223u;b[i]=float(int(seed>>16)-32768)/32768.f;}if(!save("reports/fft-custom-a.bin",a)||!save("reports/fft-custom-b.bin",b))return 2;float *da,*db,*dout;checkCudaErrors(cudaMalloc(&da,n*4));checkCudaErrors(cudaMalloc(&db,n*4));checkCudaErrors(cudaMalloc(&dout,(n+8)*4));checkCudaErrors(cudaMemcpy(da,a.data(),n*4,cudaMemcpyHostToDevice));checkCudaErrors(cudaMemcpy(db,b.data(),n*4,cudaMemcpyHostToDevice));for(int direction:{-1,1})for(int stage=0;stage<3;stage++){std::fill(out.begin(),out.end(),-77);checkCudaErrors(cudaMemcpy(dout,out.data(),out.size()*4,cudaMemcpyHostToDevice));if(stage==0)spPostprocess2D(dout,da,y,x,padding,direction);if(stage==1)spPreprocess2D(dout,da,y,x,padding,direction);if(stage==2)spProcess2D(dout,da,db,y,x,direction);checkCudaErrors(cudaMemcpy(out.data(),dout,out.size()*4,cudaMemcpyDeviceToHost));char path[150];snprintf(path,sizeof(path),"reports/fft-custom-%d-%d.bin",direction,stage);if(!save(path,out))return 2;printf("Captured original custom FFT stage %d, direction %d, 64x32, padding 16 and guard values.\n",stage,direction);}for(void*p:{(void*)da,(void*)db,(void*)dout})checkCudaErrors(cudaFree(p));}
